const IDX: Record<Lang, number> = { es: 0, en: 1, fr: 2, it: 3 };
export const LANGS: Lang[] = ['es', 'en', 'fr', 'it'];
export const LANG_NAMES: Record<Lang, string> = { es: 'Español', en: 'English', fr: 'Français', it: 'Italiano' };

export function translate(lang: Lang, key: keyof typeof S | string, ...vars: (string | number)[]): string {
  const row = S[key];
  if (!row) return key;
  return row[IDX[lang]].replace(/\{(\d)\}/g, (_m, i) => String(vars[Number(i)] ?? ''));
}
export type StringKey = keyof typeof S;
